/// Where a convention kind is evaluated. Exhaustively matched by the engine.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum ConventionDispatch {
    EngineDirect,
    None,
    EnginePhase6,
    Cli,
}

impl ConventionKind {
    /// The evaluator that owns this kind.
    pub fn dispatch(self) -> ConventionDispatch {
        match self {
            ConventionKind::ApiRouteNoDirectDataAccess => ConventionDispatch::EngineDirect,
            ConventionKind::ApiRouteRequiresServiceDelegation => ConventionDispatch::None,
            ConventionKind::ApiRouteRequiresAuthHelper => ConventionDispatch::EngineDirect,
            ConventionKind::MiddlewareMustCoverRoutes => ConventionDispatch::None,
            ConventionKind::ApiRouteRequiresRequestValidation => ConventionDispatch::EngineDirect,
            ConventionKind::ApiRouteForbidsUntrustedSsrf => ConventionDispatch::EnginePhase6,
            ConventionKind::ApiRouteForbidsRawSqlWithoutParams => ConventionDispatch::EnginePhase6,
            ConventionKind::ApiRouteCorsMustMatchPolicy => ConventionDispatch::EnginePhase6,
            ConventionKind::ApiRouteRequiresCsrfForMutation => ConventionDispatch::EnginePhase6,
            ConventionKind::ApiRouteRequiresRateLimit => ConventionDispatch::EnginePhase6,
            ConventionKind::ApiRouteForbidsSensitiveResponseFields => {
                ConventionDispatch::EngineDirect
            }
            ConventionKind::ApiRouteForbidsSecretExposure => ConventionDispatch::EngineDirect,
            ConventionKind::SessionObjectMustComeFromTrustedHelper => {
                ConventionDispatch::EngineDirect
            }
            ConventionKind::ApiRouteRequiresAuthorization => ConventionDispatch::EngineDirect,
            ConventionKind::ApiRouteRequiresTenantScope => ConventionDispatch::EngineDirect,
            ConventionKind::TestExpectedForChangedModule => ConventionDispatch::None,
            ConventionKind::CustomBriefing => ConventionDispatch::None,
            ConventionKind::FileRole => ConventionDispatch::Cli,
            ConventionKind::ModulePlacement => ConventionDispatch::Cli,
            ConventionKind::ImportBoundary => ConventionDispatch::Cli,
            ConventionKind::EntrypointFlow => ConventionDispatch::Cli,
            ConventionKind::CanonicalHelperReuse => ConventionDispatch::Cli,
            ConventionKind::RequiredChangeChecks => ConventionDispatch::Cli,
        }
    }

    /// Whether candidate inference may propose this kind.
    pub fn proposable(self) -> bool {
        match self {
            ConventionKind::ApiRouteNoDirectDataAccess => true,
            ConventionKind::ApiRouteRequiresServiceDelegation => true,
            ConventionKind::ApiRouteRequiresAuthHelper => true,
            ConventionKind::MiddlewareMustCoverRoutes => true,
            ConventionKind::ApiRouteRequiresRequestValidation => true,
            ConventionKind::ApiRouteForbidsUntrustedSsrf => true,
            ConventionKind::ApiRouteForbidsRawSqlWithoutParams => true,
            ConventionKind::ApiRouteCorsMustMatchPolicy => true,
            ConventionKind::ApiRouteRequiresCsrfForMutation => true,
            ConventionKind::ApiRouteRequiresRateLimit => true,
            ConventionKind::ApiRouteForbidsSensitiveResponseFields => true,
            ConventionKind::ApiRouteForbidsSecretExposure => true,
            ConventionKind::SessionObjectMustComeFromTrustedHelper => true,
            ConventionKind::ApiRouteRequiresAuthorization => true,
            ConventionKind::ApiRouteRequiresTenantScope => true,
            ConventionKind::TestExpectedForChangedModule => true,
            ConventionKind::CustomBriefing => true,
            ConventionKind::FileRole => false,
            ConventionKind::ModulePlacement => false,
            ConventionKind::ImportBoundary => false,
            ConventionKind::EntrypointFlow => false,
            ConventionKind::CanonicalHelperReuse => false,
            ConventionKind::RequiredChangeChecks => false,
        }
    }

    /// Whether this kind's engine evaluator re-reads the route file from disk.
    ///
    /// True for every kind whose evaluator calls `read_repo_file`. Such a kind cannot be
    /// evaluated at all without `repo_root`, and `repo_root` is optional on the wire.
    pub fn requires_engine_source(self) -> bool {
        match self {
            ConventionKind::ApiRouteNoDirectDataAccess => false,
            ConventionKind::ApiRouteRequiresServiceDelegation => false,
            ConventionKind::ApiRouteRequiresAuthHelper => true,
            ConventionKind::MiddlewareMustCoverRoutes => false,
            ConventionKind::ApiRouteRequiresRequestValidation => true,
            ConventionKind::ApiRouteForbidsUntrustedSsrf => true,
            ConventionKind::ApiRouteForbidsRawSqlWithoutParams => true,
            ConventionKind::ApiRouteCorsMustMatchPolicy => true,
            ConventionKind::ApiRouteRequiresCsrfForMutation => true,
            ConventionKind::ApiRouteRequiresRateLimit => true,
            ConventionKind::ApiRouteForbidsSensitiveResponseFields => true,
            ConventionKind::ApiRouteForbidsSecretExposure => true,
            ConventionKind::SessionObjectMustComeFromTrustedHelper => true,
            ConventionKind::ApiRouteRequiresAuthorization => true,
            ConventionKind::ApiRouteRequiresTenantScope => true,
            ConventionKind::TestExpectedForChangedModule => false,
            ConventionKind::CustomBriefing => false,
            ConventionKind::FileRole => false,
            ConventionKind::ModulePlacement => false,
            ConventionKind::ImportBoundary => false,
            ConventionKind::EntrypointFlow => false,
            ConventionKind::CanonicalHelperReuse => false,
            ConventionKind::RequiredChangeChecks => false,
        }
    }
}

/// D-S1: the one capability namespace.
///
/// These ids are what may appear in EngineCapabilityStats (certified/required/missing),
/// EngineCompleteness.{required,missing}_capabilities, and therefore in ScanCapabilityReport and the
/// semantic coverage contract built from it.
///
/// There used to be two namespaces with zero string overlap BY CONSTRUCTION: the engine emitted bare
/// names (`graph_stream`, `route_detection`) and BUILTIN_SEMANTIC_CAPABILITIES declared eight ids of
/// the form `ts.<name>.v1`. A hand-written translation table in packages/query/src/semantic-coverage.ts
/// was supposed to bridge them and named four capabilities the engine has never emitted
/// (`data_operations`, `data_operation_facts`, `fact_graph`, `route_flow`).
///
/// The bare namespace won because it is the one on the wire: nine of the eleven sites that PRODUCE a
/// capability id already emitted bare names (both Rust capability_stats call sites, repo_completeness,
